/*
 * A086391  Numbers k such that F(k^2+1) == 1 (mod k) where F(k) denotes the
 *          k-th Fibonacci number.
 * https://oeis.org/A086391
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 90, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A086391: numbers k such that F(k^2+1) ≡ 1 (mod k) */
/* The terms are generated by brute‑force search.  Fib modulo k is
 * computed by fast doubling using only arithmetic on seq_t. */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* fast doubling algorithm for Fibonacci modulo mod.
 * Returns F(n) mod mod.  n is an idx_t (uint64_t). */
static seq_t fib_mod(idx_t n, seq_t mod)
{
    seq_t a = 0;          /* F(0)  */
    seq_t b = 1;          /* F(1)  */

    for (int i = 63; i >= 0; --i)
    {
        /* doubled values: F(2k) and F(2k+1) from (a,b) = (F(k),F(k+1)) */
        seq_t two_b = (b * 2) % mod;                /* 2*F(k+1) mod mod */
        seq_t temp = (two_b + mod - a) % mod;       /* (2*F(k+1)-F(k)) mod mod */
        seq_t c = (a * temp) % mod;                 /* F(2k)   mod mod */
        seq_t d = (a * a + b * b) % mod;            /* F(2k+1) mod mod */

        if ((n >> i) & (idx_t)1U)
        {
            a = d;
            b = (c + d) % mod;
        }
        else
        {
            a = c;
            b = d;
        }
    }
    return a;   /* F(n) mod mod */
}

/* required sequence function */
seq_t a(idx_t n)
{
    static seq_t *cache = NULL;
    static size_t cache_sz = 0;
    static size_t cache_cap = 0;
    static idx_t next_k = 2;   /* the first k that might satisfy the property */

    while (cache_sz < n)
    {
        idx_t k = next_k;
        seq_t mod = (seq_t)k;

        /* compute n = k^2 + 1 (safe for k up to ~2^32) */
        idx_t fib_index = (unsigned __int128)k * k + 1;

        seq_t f = fib_mod(fib_index, mod);

        if (f == (seq_t)1 % mod)   /* 1 mod k is 1 for k >= 2 */
        {
            if (cache_sz >= cache_cap)
            {
                size_t new_cap = cache_cap ? 2 * cache_cap : 32;
                seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                if (!tmp)
                {
                    abort();   /* allocation failure */
                }
                cache = tmp;
                cache_cap = new_cap;
            }
            cache[cache_sz++] = (seq_t)k;
        }
        ++next_k;
    }

    return cache[n - 1];
}
